  const fKomNeu = await fRuf('cookie-f-carla', 'POST', '/api/items/2/comments', { text: 'Carla sagt etwas' });
  pruefe('Aber schreiben darf jeder an jedem Eintrag', fKomNeu.status === 201, `Status ${fKomNeu.status}`);

